const upsertDocumentShare = `-- name: UpsertDocumentShare :one
INSERT INTO document_shares (id, company_id, document_id, user_id, role, created_at, updated_at)
VALUES ($1, $2, $3, $4, $5, NOW(), NOW())
ON CONFLICT (document_id, user_id) 
DO UPDATE SET role = EXCLUDED.role, updated_at = NOW()
RETURNING id, company_id, document_id, user_id, role, created_at, updated_at
`

type UpsertDocumentShareParams struct {
	ID         pgtype.UUID `json:"id"`
	CompanyID  pgtype.UUID `json:"company_id"`
	DocumentID pgtype.UUID `json:"document_id"`
	UserID     pgtype.UUID `json:"user_id"`
	Role       string      `json:"role"`
}

func (q *Queries) UpsertDocumentShare(ctx context.Context, arg UpsertDocumentShareParams) (DocumentShare, error) {
	row := q.db.QueryRow(ctx, upsertDocumentShare,
		arg.ID,
		arg.CompanyID,
		arg.DocumentID,
		arg.UserID,
		arg.Role,
	)
	var i DocumentShare
	err := row.Scan(
		&i.ID,
		&i.CompanyID,
		&i.DocumentID,
		&i.UserID,
		&i.Role,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
